def interpretar(programa,acc=0):
    for op,x in programa:
        if op=='ADD': acc+=x
        elif op=='SUB': acc-=x
        elif op=='MUL': acc*=x
        else: raise ValueError('Operação desconhecida')
    return acc
assert interpretar([('ADD',5),('SUB',2),('MUL',3)])==9
try: interpretar([('X',2)])
except ValueError: pass
else: raise AssertionError('Operação deve ser rejeitada')
